-- Declared foreign keys for assets module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('asset.assets') IS NOT NULL AND to_regclass('asset.asset_categories') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('asset.assets') AND c.contype = 'f' AND a.attname = 'asset_category_id'
    ) THEN
        ALTER TABLE asset.assets ADD CONSTRAINT fk_assets_asset_category_id FOREIGN KEY (asset_category_id) REFERENCES asset.asset_categories (id) NOT VALID;
        BEGIN
            ALTER TABLE asset.assets VALIDATE CONSTRAINT fk_assets_asset_category_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_assets_asset_category_id left NOT VALID: stored rows of asset.assets reference missing rows';
        END;
    END IF;
END $$;

